CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110060230_InitialCreate') THEN
    CREATE TABLE "Bugs" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "BugName" character varying(150) NOT NULL,
        "BugDescription" character varying(2000) NOT NULL,
        "ReportDate" timestamp with time zone NOT NULL,
        "Level" character varying(20) NOT NULL,
        CONSTRAINT "PK_Bugs" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110060230_InitialCreate') THEN
    INSERT INTO "Bugs" ("Id", "BugDescription", "BugName", "Level", "ReportDate")
    VALUES (1, 'When JWT refresh token expires, the client receives HTTP 500 Internal Server Error instead of HTTP 401 Unauthorized, causing unexpected crash on user dashboard.', 'Authentication token expiration causes 500 error', 'Critical', TIMESTAMPTZ '2026-11-08T09:30:00Z');
    INSERT INTO "Bugs" ("Id", "BugDescription", "BugName", "Level", "ReportDate")
    VALUES (2, 'Payment processing fails to back off when gateway response times out, leading to duplicate charge attempts within a short interval.', 'Payment gateway timeout retry loop', 'High', TIMESTAMPTZ '2026-11-09T14:15:00Z');
    INSERT INTO "Bugs" ("Id", "BugDescription", "BugName", "Level", "ReportDate")
    VALUES (3, 'Circular avatar cropper distorts non-square uploaded images on mobile responsive viewports below 480px width.', 'Profile image avatar rendering distortion', 'Medium', TIMESTAMPTZ '2026-11-09T18:45:00Z');
    INSERT INTO "Bugs" ("Id", "BugDescription", "BugName", "Level", "ReportDate")
    VALUES (4, 'Tooltip displays ''Verfication'' instead of ''Verification'' on hover under Account Security tab.', 'Typo in user settings email verification tooltip', 'Low', TIMESTAMPTZ '2026-11-10T08:10:00Z');
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110060230_InitialCreate') THEN
    CREATE INDEX "IX_Bugs_Level" ON "Bugs" ("Level");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110060230_InitialCreate') THEN
    CREATE INDEX "IX_Bugs_ReportDate" ON "Bugs" ("ReportDate");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110060230_InitialCreate') THEN
    PERFORM setval(
        pg_get_serial_sequence('"Bugs"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Bugs") + 1,
            nextval(pg_get_serial_sequence('"Bugs"', 'Id'))),
        false);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110060230_InitialCreate') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261110060230_InitialCreate', '8.0.11');
    END IF;
END $EF$;
COMMIT;

